    [1] = {
        { t = 0.42, text = [=[The Cosmic Index of Summonable Persons is, by general agreement, the most important document in Azeroth that nobody has ever read.]=] },
        { t = 10.41, text = [=[It lists every being that may legally be summoned, in alphabetical order, and it was compiled by a single clerk who had, at the time, been on shift for nine thousand years.]=] },
    },
    [2] = {
        { t = 0.41, text = [=[Somewhere around the letter Z, the clerk sneezed.]=] },
        { t = 4.80, text = [=[This is generally accepted to be the origin of the entire problem.]=] },
    },
    [3] = {
        { t = 0.41, text = [=[As a result of the sneeze, a Licensed Summoning Liaison, Third Class, named Zennit was entered into the Index as the default recipient of every Ritual of Summoning completed within range of his name.]=] },
        { t = 14.60, text = [=[This includes rituals meant for other people.]=] },
        { t = 18.65, text = [=[It includes rituals meant for nobody.]=] },
